    // Medical consent (first-run)
    'consent.title':              'Bevor Sie beginnen',
    'consent.intro':              'Calm Parent ist ein Hilfsmittel für Eltern. Bevor Sie beginnen, müssen Sie einige wichtige Dinge wissen.',
