    'consent.p2':                 'Die App diagnostiziert oder behandelt nicht. Sie hilft Beobachtungen aufzuzeichnen — Mahlzeiten, Schlaf, Temperatur, Medikamente — damit Sie sie für den Kinderarzt zur Hand haben.',
    'consent.p3':                 'Die App ersetzt keinen Arzt. Entscheidungen über die Gesundheit Ihres Kindes treffen Sie immer gemeinsam mit dem Kinderarzt. SkuDev haftet nicht für medizinische Entscheidungen, die auf Grundlage der App getroffen werden.',
