    'features.item.sleep.detail':   'Tippen Sie, wenn das Kind einschläft, tippen Sie wieder, wenn es aufwacht. Die Stoppuhr läuft im Hintergrund, auch wenn Sie die App schließen. Sehen Sie, wie viel das Kind innerhalb eines Tages geschlafen hat.',
