    'features.item.temp.title':     'Temperatur',
    'features.item.temp.short':     'Trend-Diagramm, Warnungen',
    'features.item.temp.detail':    'Sie messen die Temperatur, speichern sie. Die App zeigt ein Diagramm und warnt, wenn das Fieber steigt, länger als 72h anhält oder Schwellenwerte überschreitet, die eine Konsultation mit einem Kinderarzt erfordern.',
    'features.item.meds.emoji':     '💊',
    'features.item.meds.title':     'Verabreichte Medikamente',
    'features.item.meds.short':     'Verlauf + Beipackzettel-Infos',
    'features.item.meds.detail':    'Erfassen Sie, was Sie wann und wie viel verabreicht haben. Die App erinnert an die Mindestabstände zwischen Dosen (gemäß Beipackzettel). Sie berechnet keine Dosierung — die überprüfen Sie selbst im Beipackzettel.',
    'features.item.diary.emoji':    '📓',
    'features.item.diary.title':    'Tagebuch und Stimmung',
    'features.item.diary.short':    'Erinnerungen und Beobachtungen festhalten',
    'features.item.diary.detail':   'Erfassen Sie interessante Momente, die Stimmung des Kindes, lustige Situationen. Als Erinnerung oder als Beobachtungen für den Arztbesuch.',
    'features.item.symptoms.emoji': '🤒',
    'features.item.symptoms.title': 'Symptome',
    'features.item.symptoms.short': 'Husten, Schnupfen, Hautausschlag, Erbrechen',
    'features.item.symptoms.detail':'Erfassen Sie Symptome mit einem Tipp. Die App warnt, wenn häufiges Erbrechen in kurzer Zeit auftritt oder wenn Hautausschlag und Fieber gemeinsam auftreten usw.',

    'features.item.crisis.emoji':   '🚨',
    'features.item.crisis.title':   'Referenzwerte',
    'features.item.crisis.short':   'Entscheidungshilfe, wenn das Kind krank ist',
    'features.item.crisis.detail':  'Wenn die Temperatur einen Schwellenwert überschreitet, zeigt die App eine Karte mit klarer Empfehlung: beobachten, Kinderarzt kontaktieren oder 112 rufen. Kein Googeln um 3 Uhr morgens.',
    'features.item.pdf_report.emoji':'📄',
    'features.item.pdf_report.title':'PDF-Bericht für den Kinderarzt',
    'features.item.pdf_report.short':'7 / 14 / 30 Tage Verlauf für den Arztbesuch',
    'features.item.pdf_report.detail':'Mit einem Tipp generieren Sie ein PDF: Diagramme von Temperatur, Mahlzeiten, Schlaf, verabreichten Medikamenten, Symptomen. Sie nehmen es zum Arztbesuch mit oder schicken es per E-Mail an den Arzt.',
    'features.item.doctor_notes.emoji':'📝',
