    'features.item.doctor_notes.short':'Diagnose, Empfehlungen, Medikamente',
    'features.item.doctor_notes.detail':'Schreiben Sie nach dem Arztbesuch auf, was der Arzt gesagt hat — Diagnose, Empfehlungen, welche Medikamente. Beim nächsten Mal müssen Sie sich nichts merken, alles ist zur Hand.',
    'features.item.vaccinations.emoji':'💉',
