    'features.item.vaccinations.short':'STIKO-Empfehlungen',
    'features.item.vaccinations.detail':'Eingebauter STIKO-Impfkalender — die App zeigt, welche Impfungen in welchem Alter fällig sind. Sie erfassen Datum, Chargennummer, Nebenwirkungen.',

