    'features.item.profiles.short': 'Zwillinge, Geschwister — Daten getrennt',
    'features.item.profiles.detail':'Erstellen Sie ein Profil für jedes Kind. Sie wechseln mit einem Tipp am oberen Bildschirmrand. Daten vermischen sich nicht zwischen Kindern.',
    'features.item.sync.emoji':     '☁️',
