    'consent.title':              'Avant de commencer',
    'consent.intro':              'Calm Parent est un outil pour les parents. Avant de commencer, vous devez connaître quelques points importants.',
    'consent.p1':                 'L\'application n\'est pas un dispositif médical. Elle ne calcule pas de posologies de médicaments, les seuils et messages sont indicatifs (recommandations SFP/HAS sur la fièvre).',
    'consent.p2':                 'L\'application ne diagnostique pas et ne traite pas. Elle aide à enregistrer les observations — repas, sommeil, température, médicaments — pour les avoir sous la main lors du rendez-vous chez le pédiatre.',
    'consent.p3':                 'L\'application ne remplace pas un médecin. Les décisions concernant la santé de votre enfant se prennent toujours avec le pédiatre. SkuDev n\'est pas responsable des décisions médicales prises sur la base de l\'application.',
    'consent.p4':                 'En cas de danger vital, appelez le 112 ou le 15 (SAMU), ou rendez-vous directement aux urgences les plus proches. L\'application ne remplace pas les services d\'urgence.',
